const CACHE='nour-v4';
const ASSETS=['./','./index.html','./styles.css','./app.js','./manifest.webmanifest','./icon.svg','./icon-180.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;const url=new URL(event.request.url);if(url.origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request)))});
self.addEventListener('push',event=>{let data={};try{data=event.data?.json()||{}}catch{data={title:'Nour',body:event.data?.text()||'It is time to pray.'}}const title=data.title||'Nour';const options={body:data.body||'It is time to pray.',icon:'./icon-180.png',badge:'./icon-180.png',tag:data.tag||'nour-prayer',data:{url:data.url||'./'},lang:'en',dir:'ltr'};event.waitUntil(self.registration.showNotification(title,options))});
self.addEventListener('notificationclick',event=>{event.notification.close();const target=new URL(event.notification.data?.url||'./',self.location.origin).href;event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(windows=>{for(const client of windows){if(client.url.startsWith(self.location.origin)&&'focus'in client){client.navigate(target);return client.focus()}}return clients.openWindow(target)}))});
